#!/usr/bin/env node
// Plank join. Reports every step-definition pattern with the scenarios that bind it, and
// reddens where a plank fails the join. Also carries the verification-conformance part.
// Derived by Shipwright at fitting out. Vanilla JavaScript project, docblock reader.

import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();
const IMPLEMENTATION = ['js'];
const SPECS = ['features'];
const VERIFICATION = ['features/steps', 'features/support'];
const RULES = 'scantlings/verification-conformance.json';

function walk(dir, ext) {
  const abs = path.join(ROOT, dir);
  if (!fs.existsSync(abs)) return [];
  const out = [];
  for (const entry of fs.readdirSync(abs, { withFileTypes: true })) {
    const rel = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...walk(rel, ext));
    else if (entry.name.endsWith(ext)) out.push(rel);
  }
  return out;
}

const failures = [];
const fail = (msg) => failures.push(msg);

// --- step definitions -------------------------------------------------------
const stepFiles = VERIFICATION.flatMap((dir) => walk(dir, '.js'));
const patterns = [];
for (const file of stepFiles) {
  const src = fs.readFileSync(path.join(ROOT, file), 'utf8');
  const re = /\b(Given|When|Then)\s*\(\s*(['"`])((?:\\.|(?!\2).)*)\2/g;
  let m;
  while ((m = re.exec(src)) !== null) patterns.push({ keyword: m[1], pattern: m[3], file });
}

// --- scenarios and steps ----------------------------------------------------
const specFiles = SPECS.flatMap((dir) => walk(dir, '.feature'));
const scenarios = [];
for (const file of specFiles) {
  const lines = fs.readFileSync(path.join(ROOT, file), 'utf8').split('\n');
  let current = null;
  let tags = [];
  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith('@')) { tags = trimmed.split(/\s+/); continue; }
    const head = /^(Scenario|Scenario Outline|Example):\s*(.+)$/.exec(trimmed);
    if (head) {
      current = { ref: `${file}:${head[2].trim()}`, tags, steps: [] };
      scenarios.push(current);
      tags = [];
      continue;
    }
    const step = /^(Given|When|Then|And|But)\s+(.+)$/.exec(trimmed);
    if (step && current) current.steps.push(step[2].trim());
  }
}

function toRegExp(pattern) {
  if (pattern.startsWith('^') || pattern.endsWith('$')) return new RegExp(pattern);
  const escaped = pattern
    .replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    .replace(/\\\{string\\\}/g, '"([^"]*)"')
    .replace(/\\\{int\\\}/g, '(-?\\d+)')
    .replace(/\\\{float\\\}/g, '(-?\\d*\\.?\\d+)')
    .replace(/\\\{word\\\}/g, '(\\S+)')
    .replace(/\\\{\\\}/g, '(.*)');
  return new RegExp(`^${escaped}$`);
}

const join = new Map();
for (const p of patterns) join.set(p.pattern, []);
for (const scenario of scenarios) {
  for (const step of scenario.steps) {
    for (const p of patterns) {
      if (toRegExp(p.pattern).test(step)) {
        const bound = join.get(p.pattern);
        if (!bound.includes(scenario.ref)) bound.push(scenario.ref);
      }
    }
  }
}

// --- planks -----------------------------------------------------------------
const implFiles = IMPLEMENTATION.flatMap((dir) => walk(dir, '.js'));
const planks = [];
const DECLARATION = /^\s*(export\s+)?(async\s+)?(function|class|const|let|var)\s/;
for (const file of implFiles) {
  const lines = fs.readFileSync(path.join(ROOT, file), 'utf8').split('\n');
  let block = null;
  lines.forEach((line, index) => {
    const trimmed = line.trim();
    if (trimmed.startsWith('/**')) block = { tags: [], start: index };
    if (block && /@planks(-provisional)?\s*\(/.test(trimmed)) {
      const m = /@planks(-provisional)?\s*\(\s*(['"])(.*?)\2\s*\)/.exec(trimmed);
      if (!m) fail(`${file}:${index + 1}: malformed plank annotation`);
      else block.tags.push({ provisional: Boolean(m[1]), value: m[3], line: index + 1 });
    } else if (!block && /@planks(-provisional)?\s*\(/.test(trimmed)) {
      fail(`${file}:${index + 1}: plank token outside a docblock`);
    }
    if (block && trimmed.endsWith('*/')) {
      const next = lines[index + 1] || '';
      if (block.tags.length > 0 && !DECLARATION.test(next))
        fail(`${file}:${block.start + 1}: plank docblock does not precede a declaration`);
      for (const tag of block.tags) planks.push({ ...tag, file, seam: next.trim() });
      block = null;
    }
  });
  const seams = lines.filter((line) => /^(export\s+)?(async\s+)?(function|class)\s/.test(line));
  if (seams.length > 0 && planks.filter((p) => p.file === file).length === 0)
    fail(`${file}: behaviour-bearing seam carries no plank`);
}

const patternSet = new Set(patterns.map((p) => p.pattern));
const captainScenarios = new Set(
  scenarios.filter((s) => s.tags.includes('@captain')).map((s) => s.ref),
);
for (const plank of planks) {
  if (plank.provisional) {
    if (!captainScenarios.has(plank.value))
      fail(`${plank.file}:${plank.line}: provisional plank "${plank.value}" names no @captain scenario`);
  } else if (!patternSet.has(plank.value)) {
    fail(`${plank.file}:${plank.line}: plank "${plank.value}" matches no current step-definition pattern`);
  }
}

for (const [pattern, bound] of join) {
  if (bound.length === 0) fail(`orphaned step definition: "${pattern}" binds no scenario`);
}

// --- conformance part -------------------------------------------------------
let conformanceFailures = 0;
const rulesPath = path.join(ROOT, RULES);
if (fs.existsSync(rulesPath)) {
  const ruleSet = JSON.parse(fs.readFileSync(rulesPath, 'utf8'));
  const supportFiles = VERIFICATION.flatMap((dir) => walk(dir, '.js'));
  for (const file of supportFiles) {
    const lines = fs.readFileSync(path.join(ROOT, file), 'utf8').split('\n');
    lines.forEach((line, index) => {
      if (/@exceptional-double/.test(line)) return;
      const previous = lines[index - 1] || '';
      if (/@exceptional-double/.test(previous)) return;
      for (const rule of ruleSet.rules) {
        if (new RegExp(rule.pattern).test(line)) {
          conformanceFailures += 1;
          console.log(`conformance: ${file}:${index + 1}: ${rule.id}: ${rule.message}`);
        }
      }
    });
  }
} else {
  console.log(`conformance: rule set ${RULES} is absent`);
  conformanceFailures += 1;
}

// --- report -----------------------------------------------------------------
console.log(`step-definition patterns: ${patterns.length}`);
for (const [pattern, bound] of join) console.log(`  "${pattern}" -> ${bound.join(', ') || '(none)'}`);
console.log(`planked seams: ${planks.length}`);
for (const plank of planks)
  console.log(`  ${plank.file}:${plank.line} ${plank.provisional ? 'provisional ' : ''}"${plank.value}"`);
console.log(`conformance findings: ${conformanceFailures}`);
for (const message of failures) console.log(`join: ${message}`);
console.log(`join failures: ${failures.length}`);
process.exit(failures.length + conformanceFailures > 0 ? 1 : 0);

{
  "name": "verification-conformance",
  "description": "Static rules over verification support code. Each rule reddens a Verification agreement breach. Text-pattern rules: this stack carries no structural query engine for verification support, so a rule can miss a breach written in another form.",
  "rules": [
    {
      "id": "no-guessed-delay",
      "pattern": "setTimeout\\s*\\(\\s*(?:[^,]*,\\s*)?\\d+\\s*\\)|await\\s+(?:new\\s+Promise|sleep|delay)\\s*\\(",
      "message": "guessed delay where a signal is observable"
    },
    {
      "id": "no-hand-authored-double",
      "pattern": "\\b(sinon|jest\\.(?:fn|mock)|createStub|createMock|fakeLocalStorage|stubDocument)\\b",
      "message": "test double outside the @exceptional-double conditions"
    },
    {
      "id": "no-hand-built-dom",
      "pattern": "new\\s+Window\\s*\\(|document\\.createElement\\s*\\(\\s*['\"]li['\"]",
      "message": "hand-built DOM instead of the real page and the real app"
    },
    {
      "id": "no-per-scenario-ambient-rebuild",
      "pattern": "require\\s*\\(\\s*['\"]node:child_process['\"]\\s*\\)",
      "message": "process spawn in verification support; ambient state is built once per run"
    }
  ]
}

